  {id:'GM-2372',first:'Karim',last:'Fathy',email:'karim.fathy@email.com',plan:'Off-Peak Monthly',status:'Active',joined:'2025-07-02',end:'2026-12-02',visits:16,initials:'KF'},
  {id:'GM-2364',first:'Laila',last:'Mostafa',email:'laila.m@email.com',plan:'Quarterly Flex',status:'Active',joined:'2025-04-15',end:'2027-01-15',visits:7,initials:'LM'}
