const trainers = [{name:'Mina George',specialty:'Strength & Conditioning',sessions:5,initials:'MG'},{name:'Nadia Hassan',specialty:'Yoga & Pilates',sessions:4,initials:'NH'},{name:'Tarek Amin',specialty:'Indoor Cycling',sessions:3,initials:'TA'}];
let members = load('gymos-members',seedMembers), activity = load('gymos-activity',seedActivity), page = 'dashboard', filter = 'All members', query = '';
function load(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function save(){localStorage.setItem('gymos-members',JSON.stringify(members));localStorage.setItem('gymos-activity',JSON.stringify(activity))}
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const today=new Date(); $('#today-label').textContent=today.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
const navNames={dashboard:'Overview',members:'Members',attendance:'Attendance',classes:'Classes',trainers:'Trainers',reports:'Reports',settings:'Settings'};
function go(name){page=name;history.replaceState(null,'','#'+name);$$('.nav-link[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===name));$('#breadcrumb-current').textContent=navNames[name];render()}
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(navNames[h])go(h)});
$$('.nav-link[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();go(a.dataset.page);$('#sidebar').classList.remove('open');$('.overlay').classList.remove('visible')}));
function fmtDate(s){return new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function statusClass(s){return s==='Active'?'status-active':s==='Expiring soon'?'status-expiring':s==='Frozen'?'status-frozen':'status-inactive'}
function memberRows(list){return list.map(m=>`<tr><td><div class="member-cell"><div class="avatar">${m.initials}</div><span><strong>${m.first} ${m.last}</strong><small>${m.id}</small></span></div></td><td>${m.plan}</td><td><span class="status ${statusClass(m.status)}">${m.status}</span></td><td>${fmtDate(m.end)}</td><td>${m.visits} visits</td><td><button class="icon-button" aria-label="Member actions" onclick="memberAction('${m.id}')">···</button></td></tr>`).join('')}
function table(list,tools=true){return `${tools?`<div class="table-tools"><label class="search-box"><span>⌕</span><input id="member-search" placeholder="Search name, email or member ID" value="${query}"></label><select id="member-filter" class="filter-select"><option>All members</option><option>Active</option><option>Expiring soon</option><option>Frozen</option></select></div>`:''}<div class="table-wrap"><table><thead><tr><th>Member</th><th>Membership plan</th><th>Status</th><th>Renewal date</th><th>Activity</th><th></th></tr></thead><tbody>${list.length?memberRows(list):'<tr><td colspan="6"><div class="empty-state">No members match your search.</div></td></tr>'}</tbody></table></div><div class="table-footer"><span>Showing ${list.length} of ${members.length} members</span><span>Updated just now</span></div>`}
function card(title,sub,body,extra=''){return `<section class="panel"><div class="panel-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>${body}</section>`}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`}
function stats(){const active=members.filter(m=>m.status==='Active').length;return `<div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>Total members</span><span class="stat-icon">♙</span></div><div class="stat-value">${(members.length+1234).toLocaleString()}</div><div class="stat-foot"><span class="trend">↗ 8.2%</span> vs. last month</div></article><article class="stat-card"><div class="stat-top"><span>Active memberships</span><span class="stat-icon">✳</span></div><div class="stat-value">${(active+1086).toLocaleString()}</div><div class="stat-foot"><span class="trend">↗ 4.6%</span> vs. last month</div></article><article class="stat-card"><div class="stat-top"><span>Check-ins today</span><span class="stat-icon">◷</span></div><div class="stat-value">148</div><div class="stat-foot"><span class="trend">↗ 12.4%</span> vs. last Tuesday</div></article><article class="stat-card"><div class="stat-top"><span>Revenue this month</span><span class="stat-icon">↗</span></div><div class="stat-value">EGP 186k</div><div class="stat-foot"><span class="trend">↗ 6.8%</span> vs. last month</div></article></div>`}
function chart(){return `<svg viewBox="0 0 560 180" preserveAspectRatio="none" aria-label="Weekly attendance trend"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#a8cf72" stop-opacity=".27"/><stop offset="1" stop-color="#a8cf72" stop-opacity="0"/></linearGradient></defs><g class="chart-grid"><line x1="35" y1="20" x2="555" y2="20"/><line x1="35" y1="60" x2="555" y2="60"/><line x1="35" y1="100" x2="555" y2="100"/><line x1="35" y1="140" x2="555" y2="140"/></g><g fill="#9aa59e" font-size="8"><text x="2" y="23">200</text><text x="4" y="63">150</text><text x="4" y="103">100</text><text x="11" y="143">50</text></g><path d="M35 120 C65 112 75 78 110 90 S155 105 184 72 S225 87 258 65 S300 84 331 55 S373 69 405 44 S455 65 480 35 S525 45 555 22 L555 155 L35 155Z" fill="url(#fill)"/><path d="M35 120 C65 112 75 78 110 90 S155 105 184 72 S225 87 258 65 S300 84 331 55 S373 69 405 44 S455 65 480 35 S525 45 555 22" fill="none" stroke="#83ab54" stroke-width="2.5" stroke-linecap="round"/><circle cx="405" cy="44" r="4" fill="#fff" stroke="#83ab54" stroke-width="2"/></svg><div class="chart-labels"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div>`}
function occupancy(){return `<section class="panel occupancy-panel"><div class="panel-heading"><div><h2>Live occupancy</h2><p>People currently in your club</p></div><span class="occupancy-live"><i></i> LIVE</span></div><div class="occupancy-number">136<span> / 200</span></div><div class="occupancy-caption">Comfortable capacity</div><div class="occupancy-progress"><span></span></div><div class="occupancy-bottom"><span>0</span><span><strong>68%</strong> capacity</span><span>200</span></div><div class="occupancy-footer"><span>Last synced</span><strong>Just now · Front desk</strong></div></section>`}
function dashboard(){return `${heading('TUESDAY, NOVEMBER 17','Good morning, Ahmed 👋','Here’s what’s happening at your club today.',`<button class="btn btn-outline" onclick="go('attendance')">◷ &nbsp;View attendance</button><button class="btn btn-lime" onclick="openMemberModal()">＋ &nbsp;Add member</button>`)}${stats()}<div class="dashboard-grid">${card('Attendance','Check-ins across the week',`<div class="chart-wrap">${chart()}</div>`,`<select class="select-mini"><option>This week</option><option>Last week</option></select>`)}${occupancy()}</div><div class="bottom-grid">${card('Quick actions','Common tasks, one click away',`<div class="quick-grid"><button class="quick-action" onclick="openMemberModal()"><span class="quick-icon">＋</span><span>Add a member</span></button><button class="quick-action" onclick="checkIn()"><span class="quick-icon">⌁</span><span>Record check-in</span></button><button class="quick-action" onclick="go('classes')"><span class="quick-icon">▦</span><span>Manage classes</span></button><button class="quick-action" onclick="go('reports')"><span class="quick-icon">↗</span><span>View reports</span></button></div>`)}${card('Recent activity','Latest at Downtown Club',`<div class="activity-list">${activity.slice(0,4).map(x=>`<div class="activity-item"><div class="avatar">${x.initials}</div><div class="activity-copy"><strong>${x.name}</strong><small>${x.action}</small></div><span class="activity-time">${x.time}</span></div>`).join('')}</div>`,`<button class="btn btn-small btn-outline" onclick="go('attendance')">View all</button>`)}</div>`}
function membersPage(){let filtered=members.filter(m=>`${m.first} ${m.last} ${m.id} ${m.email}`.toLowerCase().includes(query.toLowerCase()));if(filter!=='All members')filtered=filtered.filter(m=>m.status===filter);return `${heading('YOUR COMMUNITY','Members','Manage your members and their memberships.',`<button class="btn btn-lime" onclick="openMemberModal()">＋ &nbsp;Add member</button>`)}<div class="panel">${table(filtered)}</div>`}
function attendancePage(){return `${heading('CLUB ACTIVITY','Attendance','A live view of today’s check-ins and club capacity.',`<button class="btn btn-lime" onclick="checkIn()">＋ &nbsp;Record check-in</button>`)}<div class="dashboard-grid">${occupancy()}${card('Today at a glance','Tuesday, November 17',`<div class="split-panel"><div><div class="eyebrow">CHECK-INS</div><div class="stat-value">148</div><span class="trend">↗ 12.4% vs last Tuesday</span></div><div><div class="eyebrow">PEAK HOUR</div><div class="stat-value">06<span style="font-size:14px"> PM</span></div><span class="stat-foot">Most visits between 6–7 PM</span></div></div>`)}</div>${card('Recent check-ins','Latest member activity',`<div class="activity-list">${[...activity,...seedActivity].slice(0,7).map(x=>`<div class="activity-item"><div class="avatar">${x.initials}</div><div class="activity-copy"><strong>${x.name}</strong><small>${x.action}</small></div><span class="activity-time">${x.time}</span></div>`).join('')}</div>`)}`}
function classesPage(){return `${heading('WHAT’S ON','Classes','Today’s schedule at Downtown Club.',`<button class="btn btn-lime" onclick="toast('Class creation is ready to connect to your schedule.')">＋ &nbsp;Add a class</button>`)}<div class="stats-grid"><article class="stat-card"><div class="stat-top">Classes today<span class="stat-icon">▦</span></div><div class="stat-value">8</div><div class="stat-foot">Across 2 studios</div></article><article class="stat-card"><div class="stat-top">Booked spots<span class="stat-icon">♙</span></div><div class="stat-value">74</div><div class="stat-foot">Across all classes today</div></article><article class="stat-card"><div class="stat-top">Average fill rate<span class="stat-icon">↗</span></div><div class="stat-value">76%</div><div class="stat-foot"><span class="trend">↗ 5.2%</span> this week</div></article><article class="stat-card"><div class="stat-top">Waitlisted<span class="stat-icon">◷</span></div><div class="stat-value">3</div><div class="stat-foot">Members awaiting a spot</div></article></div>${card('Today’s classes','Tuesday, November 17',`<div class="list-rows">${seedClasses.map(c=>`<div class="list-row"><div class="stat-icon">▦</div><div class="list-row-main"><strong>${c.name}</strong><small>${c.time} · ${c.trainer}</small></div><span class="pill">${c.spots}</span><button class="btn btn-small btn-outline" onclick="toast('Class roster opened.')">Roster</button></div>`).join('')}</div>`)}`}
function trainersPage(){return `${heading('YOUR COACHES','Trainers','Meet the team leading classes this week.',`<button class="btn btn-lime" onclick="toast('Trainer invitations will be available when staff accounts are connected.')">＋ &nbsp;Add trainer</button>`)}<div class="split-panel">${trainers.map(t=>`<section class="panel"><div class="member-cell"><div class="avatar" style="width:42px;height:42px">${t.initials}</div><span><strong>${t.name}</strong><small>${t.specialty}</small></span><span class="pill">Active</span></div><div class="setting-row"><span><strong>${t.sessions} sessions</strong><small>Scheduled today</small></span><button class="btn btn-small btn-outline" onclick="toast('Trainer schedule opened.')">View schedule</button></div></section>`).join('')}</div>`}
function reportsPage(){return `${heading('CLUB PERFORMANCE','Reports','A quick look at the numbers that move your club forward.',`<button class="btn btn-outline" onclick="toast('Report export is ready to connect to your data source.')">↓ &nbsp;Export report</button>`)}<div class="report-cards"><section class="panel report-card"><div class="eyebrow">MEMBERSHIP GROWTH</div><strong>+8.2%</strong><p>New memberships compared with last month</p></section><section class="panel report-card"><div class="eyebrow">VISIT FREQUENCY</div><strong>3.4×</strong><p>Average weekly visits per active member</p></section><section class="panel report-card"><div class="eyebrow">CLASS UTILIZATION</div><strong>76%</strong><p>Average class capacity booked this week</p></section></div><div style="height:15px"></div>${card('Weekly attendance','Member check-ins per day',`<div class="chart-wrap">${chart()}</div>`)}<p class="subtle-note">This pilot view uses sample figures to show the reports your club team can track. Connect your gym data before using figures for business decisions.</p>`}
function settingsPage(){return `${heading('MAKE IT YOURS','Club settings','Set up the details that make GymOS feel like your club.')}<div class="split-panel"><section class="panel"><div class="panel-heading"><div><h2>Club profile</h2><p>Details members and staff see</p></div></div><div class="setting-row"><span><strong>Club name</strong><small>Downtown Club</small></span><button class="btn btn-small btn-outline" onclick="toast('Club profile editor opened.')">Edit</button></div><div class="setting-row"><span><strong>Currency</strong><small>Egyptian Pound (EGP)</small></span><button class="btn btn-small btn-outline" onclick="toast('Currency settings opened.')">Edit</button></div><div class="setting-row"><span><strong>Branch capacity</strong><small>200 members at one time</small></span><button class="btn btn-small btn-outline" onclick="toast('Capacity settings opened.')">Edit</button></div></section><section class="panel"><div class="panel-heading"><div><h2>Features</h2><p>Choose what your pilot team uses</p></div></div>${[['Class bookings','Let members reserve a class'],['Trainer bookings','Allow personal training requests'],['Nutrition','Show nutrition tools in member app']].map(([a,b],i)=>`<div class="setting-row"><span><strong>${a}</strong><small>${b}</small></span><button class="switch ${i<2?'on':''}" aria-label="Toggle ${a}" onclick="this.classList.toggle('on');toast('${a} setting updated.')"></button></div>`).join('')}</section></div><p class="subtle-note">Feature switches are saved for this demo session only. Your pilot gym can choose its own modules and policies before launch.</p>`}
function render(){const content=$('#content');content.innerHTML=({dashboard,members:membersPage,attendance:attendancePage,classes:classesPage,trainers:trainersPage,reports:reportsPage,settings:settingsPage}[page]||dashboard)();$('#member-nav-count').textContent=members.length||'';const search=$('#member-search'),select=$('#member-filter');if(search){search.addEventListener('input',()=>{query=search.value;const pos=search.selectionStart;render();$('#member-search').focus();$('#member-search').setSelectionRange(pos,pos)})}if(select){select.value=filter;select.addEventListener('change',()=>{filter=select.value;render()})}}
function toast(message){const t=document.createElement('div');t.className='toast';t.textContent=message;$('#toast-root').append(t);setTimeout(()=>t.remove(),3000)}
function checkIn(){const m=members[Math.floor(Math.random()*members.length)];activity.unshift({initials:m.initials,name:`${m.first} ${m.last}`,action:'checked in',time:'Just now'});activity=activity.slice(0,10);save();render();toast(`${m.first} ${m.last} checked in successfully.`)}
function openMemberModal(){ $('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="addMember(event)"><div class="modal-head"><div><h2>Add a member</h2><p>Create a member profile for your club.</p></div><button type="button" class="icon-button modal-close" onclick="closeModal()">×</button></div><div class="form-grid"><div class="form-field"><label for="first">First name</label><input id="first" name="first" required placeholder="e.g. Sara"></div><div class="form-field"><label for="last">Last name</label><input id="last" name="last" required placeholder="e.g. Hassan"></div><div class="form-field full"><label for="email">Email address</label><input id="email" name="email" type="email" required placeholder="sara@email.com"></div><div class="form-field full"><label for="plan">Membership plan</label><select id="plan" name="plan"><option>Unlimited Annual</option><option>Off-Peak Monthly</option><option>Quarterly Flex</option></select></div></div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Cancel</button><button class="btn btn-lime">Add member</button></div></form></div>`;$('#first').focus()}
function closeModal(){$('#modal-root').innerHTML=''}
function addMember(e){e.preventDefault();const f=new FormData(e.target),first=f.get('first').trim(),last=f.get('last').trim();const id='GM-'+(2402+members.length-7);const now=new Date(),end=new Date(now);end.setFullYear(end.getFullYear()+1);members.unshift({id,first,last,email:f.get('email'),plan:f.get('plan'),status:'Active',joined:now.toISOString().slice(0,10),end:end.toISOString().slice(0,10),visits:0,initials:(first[0]+last[0]).toUpperCase()});activity.unshift({initials:(first[0]+last[0]).toUpperCase(),name:`${first} ${last}`,action:'joined as a new member',time:'Just now'});save();closeModal();go('members');toast(`${first} ${last} added to your members.`)}
function memberAction(id){const m=members.find(x=>x.id===id);if(!m)return;const options=['Active','Frozen','Inactive'];const next=options[(options.indexOf(m.status)+1)%options.length];if(confirm(`Change ${m.first} ${m.last} from ${m.status} to ${next}?`)){m.status=next;save();render();toast(`Membership status updated to ${next}.`)}}
$('#menu-toggle').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('.overlay').classList.toggle('visible')});const overlay=document.createElement('div');overlay.className='overlay';overlay.onclick=()=>{$('#sidebar').classList.remove('open');overlay.classList.remove('visible')};document.body.append(overlay);
const initialHash=location.hash.slice(1);if(navNames[initialHash])page=initialHash;go(page);
